using System;using System.IO;using System.Linq;using System.Text;using System.Security.Cryptography;using UnityEngine;using UnityEditor;
public static class ColliderSnapshot109 {
 static string F(float x)=>x.ToString("R",System.Globalization.CultureInfo.InvariantCulture);
 static string V(Vector3 v)=>F(v.x)+","+F(v.y)+","+F(v.z);
 public static string MeshHash(Mesh mesh){if(!mesh||mesh.vertexCount==0)throw new Exception("Missing or empty collision mesh");using(var stream=new MemoryStream()){using(var writer=new BinaryWriter(stream,Encoding.UTF8,true)){writer.Write(mesh.vertexCount);foreach(var v in mesh.vertices){writer.Write(v.x);writer.Write(v.y);writer.Write(v.z);}writer.Write(mesh.subMeshCount);for(int s=0;s<mesh.subMeshCount;s++){writer.Write((int)mesh.GetTopology(s));var indices=mesh.GetIndices(s);writer.Write(indices.Length);foreach(var i in indices)writer.Write(i);}}using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(stream.ToArray())).Replace("-","");}}
 public static string Capture(GameObject root){var colliders=root.GetComponentsInChildren<Collider>(true);if(colliders.Length==0)throw new Exception("Collider comparison cannot accept an empty target");return string.Join("\n",colliders.Select(c=>{
 var matrix=Matrix4x4.TRS(root.transform.localPosition,root.transform.localRotation,root.transform.localScale)*root.transform.worldToLocalMatrix*c.transform.localToWorldMatrix;var basis=string.Join(",",Enumerable.Range(0,16).Select(i=>F(matrix[i])));var m=c.sharedMaterial;string material=m?string.Join(",",m.dynamicFriction,m.staticFriction,m.bounciness,m.frictionCombine,m.bounceCombine):"default";
 string detail;if(c is MeshCollider mc){if(!mc.sharedMesh)throw new Exception("MeshCollider has no mesh");detail=$"{mc.convex}/{mc.cookingOptions}/{MeshHash(mc.sharedMesh)}";}else if(c is CapsuleCollider cap)detail=V(cap.center)+"/"+F(cap.radius)+"/"+F(cap.height)+"/"+cap.direction;else if(c is BoxCollider box)detail=V(box.center)+"/"+V(box.size);else if(c is SphereCollider sphere)detail=V(sphere.center)+"/"+F(sphere.radius);else throw new Exception("Unsupported Collider type "+c.GetType().Name);
 return AnimationUtility.CalculateTransformPath(c.transform,root.transform)+"/"+c.GetType().Name+"/"+c.gameObject.layer+"/"+c.gameObject.activeSelf+"/"+c.enabled+"/"+c.isTrigger+"/"+basis+"/"+material+"/"+detail;
 }).OrderBy(x=>x,StringComparer.Ordinal));}
 public static void NegativeControls(GameObject prefab){var o=UnityEngine.Object.Instantiate(prefab);try{string original=Capture(o);var c=o.GetComponentsInChildren<MeshCollider>(true).First();var local=c.transform.localPosition;c.transform.localPosition+=new Vector3(.1f,0,0);if(Capture(o)==original)throw new Exception("Transform negative control failed");c.transform.localPosition=local;c.enabled=!c.enabled;if(Capture(o)==original)throw new Exception("Enabled negative control failed");c.enabled=!c.enabled;var source=c.sharedMesh;var copy=UnityEngine.Object.Instantiate(source);try{if(MeshHash(copy)!=MeshHash(source))throw new Exception("Mesh hash unstable");var v=copy.vertices;v[0]+=new Vector3(.01f,0,0);copy.vertices=v;if(MeshHash(copy)==MeshHash(source))throw new Exception("Geometry negative control failed");c.sharedMesh=copy;if(Capture(o)==original)throw new Exception("Mesh replacement negative control failed");c.sharedMesh=source;}finally{UnityEngine.Object.DestroyImmediate(copy);}foreach(var collider in o.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(collider);bool rejected=false;try{Capture(o);}catch{rejected=true;}if(!rejected)throw new Exception("Empty collider negative control failed");}finally{UnityEngine.Object.DestroyImmediate(o);}}
}
